void AAlsCharacter::NotifyLocomotionModeChanged(const FGameplayTag PreviousLocomotionMode)
{
	ApplyDesiredStance();

	if (LocomotionMode == AlsLocomotionModeTags::Grounded &&
	    PreviousLocomotionMode == AlsLocomotionModeTags::InAir)
	{
		if (Settings->Ragdolling.bStartRagdollingOnLand &&
		    LocomotionState.Velocity.Z <= -Settings->Ragdolling.RagdollingOnLandSpeedThreshold)
		{
			StartRagdolling();
		}
		else if (Settings->Rolling.bStartRollingOnLand &&
		         LocomotionState.Velocity.Z <= -Settings->Rolling.RollingOnLandSpeedThreshold)
		{
			static constexpr auto PlayRate{1.3f};

			StartRolling(LocomotionState.bHasVelocity
				             ? LocomotionState.VelocityYawAngle
				             : UE_REAL_TO_FLOAT(FMath::UnwindDegrees(GetActorRotation().Yaw)),
			             PlayRate);
		}
		else
		{
			// Increase friction for a short period of time to prevent sliding on the ground after landing.

			static constexpr auto HasInputBrakingFrictionFactor{0.5f};
			static constexpr auto NoInputBrakingFrictionFactor{3.0f};

			GetCharacterMovement()->BrakingFrictionFactor = LocomotionState.bHasInput
				                                                ? HasInputBrakingFrictionFactor
				                                                : NoInputBrakingFrictionFactor;

			static constexpr auto ResetDelay{0.5f};

			GetWorldTimerManager().SetTimer(BrakingFrictionFactorResetTimer,
			                                FTimerDelegate::CreateWeakLambda(this, [this]
			                                {
				                                GetCharacterMovement()->BrakingFrictionFactor = 0.0f;
			                                }), ResetDelay, false);

			// Block rotation towards the last input direction after landing to prevent
			// legs from twisting into a spiral while the landing animation is playing.

			LocomotionState.bRotationTowardsLastInputDirectionBlocked = true;
		}

#endif

	if (FindTimer(InOutHandle))
	{
		// if the timer is already set, just clear it and we'll re-add it, since 
		// there's no data to maintain.
		InternalClearTimer(InOutHandle);
	}

	if (InRate > 0.f)

		const float FirstDelay = (InTimerParameters.FirstDelay >= 0.f) ? InTimerParameters.FirstDelay : InRate;

		FTimerHandle NewTimerHandle;
#if UE_AUTORTFM
		if (bEnableTransactionalTimers && AutoRTFM::IsClosed())
		{
			// Reserve a slot in Timers for this transactional timer.
			NewTimerHandle = GenerateReservedHandleForTransaction();

			// Add the timer to TransactionalTimers.
			NewTimerData.ExpireTime = FirstDelay;
			NewTimerData.Handle = NewTimerHandle;
			TransactionalTimers.Add(NewTimerHandle, FTransactionalTimer
				{
					.NewData = MoveTemp(NewTimerData),
					.Status = HasBeenTickedThisFrame() ? FTransactionalTimer::Active : FTransactionalTimer::Pending,
				});
			MaybeRegisterTransactionalCallbacks();
		}
		else
#endif  // UE_AUTORTFM
		if (HasBeenTickedThisFrame())
		{
			NewTimerData.ExpireTime = InternalTime + FirstDelay;
			NewTimerData.Status = ETimerStatus::Active;
			NewTimerHandle = AddTimer(MoveTemp(NewTimerData));
			ActiveTimerHeap.HeapPush(NewTimerHandle, FTimerHeapOrder(Timers));
		}
		else
		{
			// Store time remaining in ExpireTime while pending
			NewTimerData.ExpireTime = FirstDelay;
			NewTimerData.Status = ETimerStatus::Pending;
			NewTimerHandle = AddTimer(MoveTemp(NewTimerData));
			PendingTimerSet.Add(NewTimerHandle);
		}

	}
#endif

	const double StartTime = FPlatformTime::Seconds();
	bool bDumpTimerLogsThresholdExceeded = false;
	int32 NbExpiredTimers = 0;

	InternalTime += DeltaTime;

if (Top->Status == ETimerStatus::ActivePendingRemoval)
{
	UE_TIMER_MANAGER_DEBUG_LOG("Removing top timer (%s) with status ActivePendingRemoval", *TopHandle.ToString());
	ActiveTimerHeap.HeapPop(TopHandle, FTimerHeapOrder(Timers), EAllowShrinking::No);
	RemoveTimer(TopHandle);
	continue;
}

if (InternalTime > Top->ExpireTime)
{
	// Timer has expired! Fire the delegate, then handle potential looping.

	if (bDumpTimerLogsThresholdExceeded)

	if( PendingTimerSet.Num() > 0 )
	{
		for (FTimerHandle Handle : PendingTimerSet)
		{
			FTimerData& TimerToActivate = GetTimer(Handle);

			// Convert from time remaining back to a valid ExpireTime
			TimerToActivate.ExpireTime += InternalTime;
			TimerToActivate.Status = ETimerStatus::Active;
			ActiveTimerHeap.HeapPush( Handle, FTimerHeapOrder(Timers) );
		}
		PendingTimerSet.Reset();
	}
}

